-- Refer to the wiki for more information.
-- https://wiki.hypr.land/configuring/
-- API reference: /usr/share/hypr/stubs/hl.meta.lua

-- Dynamic colors from wallpaper, generated by pywal from
-- .config/wal/templates/hyprland.lua. Fall back to a fixed palette so a missing
-- cache (fresh install, before the first `wal` run) can't break startup.
local ok, colors = pcall(dofile, os.getenv("HOME") .. "/.cache/wal/hyprland.lua")
if not ok then
    colors = { background = "rgb(0f1016)", color0 = "rgb(0f1016)", color4 = "rgb(dbab6c)", color5 = "rgb(2f5996)" }
end

-------------------------
--- PER MACHINE CONFIG ---
-------------------------

-- Device-specific monitors and keyboard layout, resolved per-hostname. Machines
-- without their own files fall back to carles-lpt's auto-detect config.
local function hostname()
    local file = io.open("/etc/hostname")
    if not file then return "carles-lpt" end
    local name = file:read("l")
    file:close()
    return name
end

local function load_for_host(dir, host)
    local path = os.getenv("HOME") .. "/.config/hypr/" .. dir .. "/"
    local file = io.open(path .. host .. ".lua")
    if file then
        file:close()
        dofile(path .. host .. ".lua")
    else
        dofile(path .. "carles-lpt.lua")
    end
end

local host = hostname()
load_for_host("monitors", host)
load_for_host("keyboard", host)

-- Import the rest of the config
dofile(os.getenv("HOME") .. "/.config/hypr/configs/keybindings.lua")

-- Set programs that you use
local terminal = "kitty"

-----------------
--- AUTOSTART ---
-----------------

-- Autostart necessary processes (like notifications daemons, status bars, etc.)
hl.on("hyprland.start", function()
    hl.exec_cmd("clipse -listen")
    hl.exec_cmd("hypridle")
    hl.exec_cmd("sleep 2 && ~/.config/hypr/scripts/wallpapers.sh")
    hl.exec_cmd("qs")
    hl.exec_cmd("blueman-applet")
    hl.exec_cmd("fcitx5 -d")

    -- set btop and nvtop in special space
    hl.exec_cmd(terminal .. " --class=btop -e btop", { workspace = "special:magic" })
    hl.exec_cmd(terminal .. " --class=nvtop -e nvtop", { workspace = "special:magic" })
end)

-----------------------------
--- ENVIRONMENT VARIABLES ---
-----------------------------

hl.env("XCURSOR_SIZE", "24")
hl.env("HYPRCURSOR_SIZE", "24")

-- Tell GTK apps to prefer dark mode
hl.env("QT_QPA_PLATFORM", "wayland")
hl.env("QT_STYLE_OVERRIDE", "kvantum")
hl.env("QT_QPA_PLATFORMTHEME", "kvantum")
hl.env("GTK_THEME", "catppuccin-mocha-blue-standard+default")

-- Input method (fcitx5). GTK_IM_MODULE is deliberately left unset so GTK apps
-- use Wayland's native text-input-v3; setting it breaks GTK4 preedit.
hl.env("XMODIFIERS", "@im=fcitx")
hl.env("QT_IM_MODULE", "fcitx")
hl.env("SDL_IM_MODULE", "fcitx")
hl.env("GLFW_IM_MODULE", "ibus")

---------------------
--- LOOK AND FEEL ---
---------------------

-- Refer to https://wiki.hypr.land/configuring/core/config-options/
hl.config({
    general = {
        gaps_in = 2,
        gaps_out = 3,

        border_size = 1,

        -- Dynamic colors from wallpaper
        col = {
            active_border = { colors = { colors.color4, colors.color5 }, angle = 90 },
            inactive_border = colors.color0,
        },

        -- Set to true enable resizing windows by clicking and dragging on borders and gaps
        resize_on_border = false,

        allow_tearing = false,

        layout = "dwindle",
    },

    decoration = {
        rounding = 5,
        rounding_power = 3.14,

        -- Change transparency of focused and unfocused windows
        active_opacity = 1.0,
        inactive_opacity = 1.0,

        shadow = {
            enabled = true,
            range = 4,
            render_power = 4,
            color = colors.background,
        },

        blur = {
            enabled = true,
            size = 3,
            passes = 1,
            vibrancy = 0.18,
        },
    },

    animations = {
        enabled = true,
    },

    dwindle = {
        preserve_split = true, -- You probably want this
    },

    master = {
        new_status = "master",
    },

    misc = {
        force_default_wallpaper = -1, -- Set to 0 or 1 to disable the anime mascot wallpapers
        disable_hyprland_logo = false, -- If true disables the random hyprland logo / anime girl background. :(
    },

    cursor = {
        no_hardware_cursors = true, -- Fix for NVIDIA cursor disappearing issues
        hide_on_key_press = false, -- Prevent cursor from hiding when typing
        inactive_timeout = 0, -- Never hide cursor due to inactivity (set to 0)
    },

    input = {
        repeat_delay = 250, -- delay before repeat starts (ms)
        repeat_rate = 40, -- repeats per second

        follow_mouse = 1,

        sensitivity = 0, -- -1.0 - 1.0, 0 means no modification.

        touchpad = {
            natural_scroll = false,
        },
    },
})

-- Quickshell's overlay surfaces, matched by the namespace each one sets.
-- The bar itself - needed for Theme.surfaceAlpha to read as frosted glass
-- rather than as the raw wallpaper showing through.
for _, namespace in ipairs({
    "quickshell",
    "quickshell-launcher",
    "quickshell-notifications",
    "quickshell-notification-center",
    "quickshell-powermenu",
    "quickshell-wallpapers",
    "quickshell-emoji",
    "quickshell-keybinds",
}) do
    hl.layer_rule({ name = "blur-" .. namespace, match = { namespace = namespace }, blur = true })
end

-- Default curves, see https://wiki.hypr.land/configuring/core/animations/
hl.curve("easeOutQuint", { type = "bezier", points = { { 0.23, 1 }, { 0.32, 1 } } })
hl.curve("easeInOutCubic", { type = "bezier", points = { { 0.65, 0.05 }, { 0.36, 1 } } })
hl.curve("linear", { type = "bezier", points = { { 0, 0 }, { 1, 1 } } })
hl.curve("almostLinear", { type = "bezier", points = { { 0.5, 0.5 }, { 0.75, 1 } } })
hl.curve("quick", { type = "bezier", points = { { 0.15, 0 }, { 0.1, 1 } } })

hl.animation({ leaf = "global", enabled = true, speed = 10, bezier = "default" })
hl.animation({ leaf = "border", enabled = true, speed = 5.39, bezier = "easeOutQuint" })
hl.animation({ leaf = "windows", enabled = true, speed = 4.79, bezier = "easeOutQuint" })
hl.animation({ leaf = "windowsIn", enabled = true, speed = 4.1, bezier = "easeOutQuint", style = "popin 87%" })
hl.animation({ leaf = "windowsOut", enabled = true, speed = 1.49, bezier = "linear", style = "popin 87%" })
hl.animation({ leaf = "fadeIn", enabled = true, speed = 1.73, bezier = "almostLinear" })
hl.animation({ leaf = "fadeOut", enabled = true, speed = 1.46, bezier = "almostLinear" })
hl.animation({ leaf = "fade", enabled = true, speed = 3.03, bezier = "quick" })
hl.animation({ leaf = "layers", enabled = true, speed = 3.81, bezier = "easeOutQuint" })
hl.animation({ leaf = "layersIn", enabled = true, speed = 4, bezier = "easeOutQuint", style = "fade" })
hl.animation({ leaf = "layersOut", enabled = true, speed = 1.5, bezier = "linear", style = "fade" })
hl.animation({ leaf = "fadeLayersIn", enabled = true, speed = 1.79, bezier = "almostLinear" })
hl.animation({ leaf = "fadeLayersOut", enabled = true, speed = 1.39, bezier = "almostLinear" })
hl.animation({ leaf = "workspaces", enabled = true, speed = 1.94, bezier = "almostLinear", style = "fade" })
hl.animation({ leaf = "workspacesIn", enabled = true, speed = 1.21, bezier = "almostLinear", style = "fade" })
hl.animation({ leaf = "workspacesOut", enabled = true, speed = 1.94, bezier = "almostLinear", style = "fade" })
hl.animation({ leaf = "zoomFactor", enabled = true, speed = 7, bezier = "quick" })

