-- See https://wiki.hypr.land/configuring/core/rules/
hl.window_rule({
    name = "clipse",
    match = { class = "clipse", float = true, focus = true },
    size = "622 652",
    center = true,
})

hl.window_rule({
    name = "blueman-manager",
    match = { class = "blueman-manager", float = true, focus = true },
    size = "622 652",
    center = true,
})

hl.window_rule({
    name = "Volume Control",
    match = { title = "Volume Control", float = true, focus = true },
    size = "622 652",
    center = true,
})

-- picture-in-picture windowrule
hl.window_rule({
    name = "firefox-pip",
    match = { class = "^firefox$", title = "^Picture-in-Picture$" },
    float = true,
    pin = true,
    keep_aspect_ratio = true,
    size = "25% 25%",
    move = "73% 5%",
})

-- Ignore maximize requests from apps. You'll probably like this.
hl.window_rule({
    name = "suppress-maximize-events",
    match = { class = ".*" },
    suppress_event = "maximize",
})

-- Fix some dragging issues with XWayland
hl.window_rule({
    name = "fix-xwayland-drags",
    match = {
        class = "^$",
        title = "^$",
        xwayland = true,
        float = true,
        fullscreen = false,
        pin = false,
    },
    no_focus = true,
})
